({
  _ensureData() {
    if (!this.data) this.data = {};
    if (!Array.isArray(this.data.readings)) {
      this.data.readings = [];
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', "Data must be an object");
    this.invariant(Array.isArray(this.data.readings), "Readings must be an array");
    for (let i = 0; i < this.data.readings.length; i++) {
      const r = this.data.readings[i];
      this.invariant(r && typeof r === 'object', "Reading entry must be an object");
      this.invariant(typeof r.value === 'number' && !Number.isNaN(r.value), "Reading value must be a valid number");
      this.invariant(typeof r.unit === 'string' && r.unit.length > 0, "Reading unit must be a non-empty string");
      this.invariant(r.timestamp !== undefined && r.timestamp !== null, "Reading must have a valid timestamp");
    }
  },

  _normalizeUnit(unit) {
    if (typeof unit !== 'string') return null;
    const u = unit.trim().toUpperCase();
    if (u === 'C' || u === 'CELSIUS') return 'C';
    if (u === 'F' || u === 'FAHRENHEIT') return 'F';
    if (u === 'K' || u === 'KELVIN') return 'K';
    return null;
  },

  _convert(value, fromUnit, toUnit) {
    const from = this._normalizeUnit(fromUnit);
    const to = this._normalizeUnit(toUnit);
    this.ensure(from !== null, `Invalid source unit: ${fromUnit}`);
    this.ensure(to !== null, `Invalid target unit: ${toUnit}`);

    if (from === to) return value;

    let inCelsius;
    if (from === 'C') {
      inCelsius = value;
    } else if (from === 'F') {
      inCelsius = (value - 32) * (5 / 9);
    } else if (from === 'K') {
      inCelsius = value - 273.15;
    }

    let result;
    if (to === 'C') {
      result = inCelsius;
    } else if (to === 'F') {
      result = inCelsius * (9 / 5) + 32;
    } else if (to === 'K') {
      result = inCelsius + 273.15;
    }

    return result;
  },

  init(msg) {
    this._ensureData();
    this._checkInvariants();
    return { initialized: true };
  },

  recordTemp(msg) {
    const payload = msg?.payload || {};
    const { value, unit, timestamp } = payload;

    this.ensure(typeof value === 'number' && !Number.isNaN(value), "value must be a valid number");
    this.ensure(typeof unit === 'string' && this._normalizeUnit(unit) !== null, "unit must be a recognized temperature unit ('C', 'F', 'K')");

    this._ensureData();
    const initialCount = this.data.readings.length;

    const normUnit = this._normalizeUnit(unit);
    const recordedTimestamp = timestamp !== undefined && timestamp !== null ? timestamp : Date.now();

    const record = {
      value,
      unit: normUnit,
      timestamp: recordedTimestamp
    };

    this.data.readings.push(record);
    this._checkInvariants();
    this.changed('temperatureRecorded', record);

    this.ensure(this.data.readings.length === initialCount + 1, "Reading was not added to history");
    return record;
  },

  convertUnit(msg) {
    const payload = msg?.payload || {};
    const { value, from, to } = payload;

    this.ensure(typeof value === 'number' && !Number.isNaN(value), "value must be a valid number");
    this.ensure(typeof from === 'string' && this._normalizeUnit(from) !== null, "from unit must be valid ('C', 'F', 'K')");
    this.ensure(typeof to === 'string' && this._normalizeUnit(to) !== null, "to unit must be valid ('C', 'F', 'K')");

    const convertedValue = this._convert(value, from, to);
    const result = {
      value: convertedValue,
      originalValue: value,
      from: this._normalizeUnit(from),
      to: this._normalizeUnit(to)
    };

    this.ensure(typeof result.value === 'number' && !Number.isNaN(result.value), "Conversion result must be a valid number");
    return result;
  },

  getHistorySummary(msg) {
    this._ensureData();
    const readings = this.data.readings;
    const count = readings.length;

    if (count === 0) {
      const emptySummary = {
        count: 0,
        min: null,
        max: null,
        averageInCelsius: null,
        latest: null,
        readings: []
      };
      this.ensure(emptySummary.count === 0, "Empty summary must have count of 0");
      return emptySummary;
    }

    let sumC = 0;
    let minC = Infinity;
    let maxC = -Infinity;
    let minRecord = null;
    let maxRecord = null;

    for (let i = 0; i < count; i++) {
      const r = readings[i];
      const valC = this._convert(r.value, r.unit, 'C');
      sumC += valC;

      if (valC < minC) {
        minC = valC;
        minRecord = r;
      }
      if (valC > maxC) {
        maxC = valC;
        maxRecord = r;
      }
    }

    const avgC = sumC / count;
    const latest = readings[readings.length - 1];

    const summary = {
      count,
      min: {
        valueInCelsius: minC,
        reading: minRecord
      },
      max: {
        valueInCelsius: maxC,
        reading: maxRecord
      },
      averageInCelsius: avgC,
      latest,
      readings: [...readings]
    };

    this.ensure(summary.count === count, "Summary count must match readings array length");
    this.ensure(summary.latest === latest, "Summary latest must match the last recorded reading");
    return summary;
  }
})
